inputs = ['hj', 'bwa', 'cjhbv', 'dkeehv', 'exahf']
outputs = ['dj', 'bywia', 'iajdbv', 'dkeiayjv', 'eiaadf']

print("Analyzing each pair:")
for i in range(len(inputs)):
    print(f"{i}: '{inputs[i]}' -> '{outputs[i]}'")
    # Let's manually find differences
    in_str = inputs[i]
    out_str = outputs[i]

    # Find positions where strings differ
    diff_positions = []
    for j in range(min(len(in_str), len(out_str))):
        if in_str[j] != out_str[j]:
            diff_positions.append((j, in_str[j], out_str[j]))

    if len(in_str) != len(out_str):
        if len(in_str) > len(out_str):
            # Extra characters at the end in input
            for j in range(len(out_str), len(in_str)):
                diff_positions.append((j, in_str[j], None))
        else:
            # Extra characters at the end in output
            for j in range(len(in_str), len(out_str)):
                diff_positions.append((j, None, out_str[j]))

    print(f"  Differences: {diff_positions}")
    print()

