# Let me approach this more systematically by looking at what I can infer from the examples
# I'll try to build rules that work for the first few examples and check if they over-apply

inputs = ['hj', 'bwa', 'cjhbv', 'dkeehv', 'exahf']
outputs = ['dj', 'bywia', 'iajdbv', 'dkeiayjv', 'eiaadf']

# Rule 1: h -> d (works for first example, let's see if it over-applies)
rules = [('h', 'd')]
over_apps = []
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    temp = inp
    for pattern, replacement in rules:
        temp = temp.replace(pattern, replacement)
    if temp != out:
        over_apps.append((i, inp, temp))

print("After applying 'h' -> 'd':")
for i, inp, out in zip(range(len(inputs)), inputs, outputs):
    temp = inp
    for pattern, replacement in rules:
        temp = temp.replace(pattern, replacement)
    print(f"  {i}: '{inp}' -> '{temp}' (expected: '{out}') {'✓' if temp == out else '✗'}")

if over_apps:
    print("Over-applications found:")
    for i, inp, temp in over_apps:
        print(f"    {i}: '{inp}' -> '{temp}' (should be '{outputs[i]}')")
else:
    print("No over-applications")

